  const photoPicker=upHead? document.querySelector('.upload-head + .hint + *') : null
  return {
    cardh3:g(cardh3), midbold:g(midbold), remarkLabel:g(remarkLabel), hint:g(hint),
    gap_h3_to_hint: gap(cardh3,hint),
  }
})
console.log(JSON.stringify(info,null,2))
